    ('60722e7e-587a-46fb-b09c-e6e82f1b74f7'::uuid, 'period_start', '-3000', '-2500', 'journal-reversal-1-rollback:60722e7e-587a-46fb-b09c-e6e82f1b74f7:period_start', 'rollback of journal-reversal-1: period_start ''-2500'' restored on Stanydale Temple', '[{"source": "remediation_change_log:28018", "url": "remediation_change_log", "quote": "phase3:batch-0052:chunk-0001 (P3/period_start): period_start ''-3000'' -> ''-2500'' - the write this row undoes"}, {"source": "gold_standard:60722e7e-587a-46fb-b09c-e6e82f1b74f7", "url": "output/remediation/gold_standard/sites.json", "quote": "-3000 is the floor of the bucket 3000 - 1500 BC, which contains -2500. Bucket correct (plan 4.3.1)."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC'', categorize_period(-2500) = ''3000 - 1500 BC'' - the same bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The gold standard''s own note gives the settlement''s dating as 2500-2000 BC: -2500 was the more precise year. The reversal restores the bucket floor the gold standard judged; the remaining map puts the 170 same-bucket writes to the owner as ''precision upgrade or roll back''."}]'::jsonb),
